import React, { useState, useEffect } from "react";
import { sendRequest } from "./requests/requests"; // API'ye istek gönderecek fonksiyon
import "./App.css";

function App() {
  const [imageFile, setImageFile] = useState(null);
  const [secondImage, setSecondImage] = useState(null);
  const [operation, setOperation] = useState("gray");
  const [params, setParams] = useState({});
  const [resultUrl, setResultUrl] = useState("");
  const [previewUrl, setPreviewUrl] = useState("");
  const [previewSecond, setPreviewSecond] = useState("");

  // Operation değiştiğinde parametreleri güncelle
  useEffect(() => {
    const defaults = {
      binary: { threshold: 127 },
      rotate: { angle: 90 },
      zoom: { scale: 1.2 },
      contrast: { factor: 0.5 },
      median: { kernel_size: 3 },
      motion: { kernel_size: 3 },
      color: { mode: "HSV" },
      double_threshold: { low_thresh: 50, high_thresh: 150 },
      edge: { threshold1: 100, threshold2: 200 },
      crop: { x: 0, y: 0, width: 200, height: 200 },
      noise: { amount: 0.02 },
      denoise: { filter_type: "mean", kernel_size: 3 },
      morphology: { morph_op: "dilate", kernel_size: 3 },
      arithmetic: { arithmetic_op: "subtract" },
    };
    setParams(defaults[operation] || {});
    setSecondImage(null); // İkinci görseli sıfırla
    setPreviewSecond("");  // İkinci görselin önizlemesini sıfırla
    setResultUrl("");  // Sonuç URL'sini sıfırla
  }, [operation]);

  // İşlem yapıldığında backend'e istek gönder
  const handleSubmit = async () => {
    if (!imageFile) {
      alert("Lütfen bir görsel yükleyin.");
      return;
    }

    // FormData ile verileri backend'e gönderiyoruz
    const formData = new FormData();
    formData.append("operation", operation);
    formData.append("file", imageFile);
    if (secondImage) formData.append("file2", secondImage);

    Object.keys(params).forEach((key) => {
      formData.append(key, params[key]);
    });

    try {
      const data = await sendRequest({ operation, imageFile, secondImageFile: secondImage, params });

      if (data?.url) {
        setResultUrl(data.url); // İşlem sonrası gelen URL'yi göster
      } else {
        alert("İşlem başarısız oldu.");
        setResultUrl("");
      }
    } catch (error) {
      alert("Bir hata oluştu.");
    }
  };

  // Yüklenen ilk görseli işlemek için
  const handleImageChange = (e) => {
    const file = e.target.files[0];
    setImageFile(file);
    if (file) setPreviewUrl(URL.createObjectURL(file)); // Yüklenen görselin önizlemesini göster
  };

  // Yüklenen ikinci görseli işlemek için
  const handleSecondImageChange = (e) => {
    const file = e.target.files[0];
    setSecondImage(file);
    if (file) setPreviewSecond(URL.createObjectURL(file)); // İkinci görselin önizlemesini göster
  };

  // Parametreleri güncellemek için fonksiyon
  const updateParam = (key, value) => {
    setParams((prev) => ({ ...prev, [key]: value }));
  };

  // Parametreler için uygun inputları render etme
  const renderParams = () => {
    switch (operation) {
      case "binary":
        return (
          <input
            type="number"
            value={params.threshold || ""}
            onChange={(e) => updateParam("threshold", e.target.value)}
            placeholder="Threshold değeri"
          />
        );
      case "rotate":
        return (
          <input
            type="number"
            value={params.angle || ""}
            onChange={(e) => updateParam("angle", e.target.value)}
            placeholder="Açı değeri"
          />
        );
      case "zoom":
        return (
          <input
            type="number"
            value={params.scale || ""}
            onChange={(e) => updateParam("scale", e.target.value)}
            step="0.1"
            placeholder="Büyütme oranı"
          />
        );
      default:
        return null;
    }
  };

  return (
    <div className="container">
      <h2>Görüntü İşleme Uygulaması</h2>

      {/* İlk görselin yüklenmesi */}
      <input type="file" accept="image/*" onChange={handleImageChange} className="file-input" />
      <div>
        {previewUrl && <img src={previewUrl} alt="Yüklenen Görsel" className="preview-image" />}
      </div>

      {/* İkinci görselin yüklenmesi (varsa) */}
      <input type="file" accept="image/*" onChange={handleSecondImageChange} className="file-input" />
      <div>
        {previewSecond && <img src={previewSecond} alt="İkinci Görsel" className="preview-image" />}
      </div>

      {/* İşlem seçimi */}
      <select className="dropdown" value={operation} onChange={(e) => setOperation(e.target.value)}>
        <option value="gray">Gri Dönüşüm</option>
        <option value="binary">Binary</option>
        <option value="rotate">Döndürme</option>
        <option value="crop">Kırpma</option>
        <option value="zoom">Yaklaştırma</option>
        <option value="color">Renk Uzamı</option>
        <option value="histogram">Histogram</option>
        <option value="contrast">Kontrast Azalt</option>
        <option value="median">Median</option>
        <option value="double_threshold">Çift Eşik</option>
        <option value="edge">Kenar Bulma</option>
        <option value="noise">Gürültü Ekle</option>
        <option value="denoise">Gürültü Temizle</option>
        <option value="motion">Motion Blur</option>
        <option value="morphology">Morfoloji</option>
        <option value="arithmetic">Aritmetik İşlem</option>
      </select>

      {/* Parametre inputları */}
      {renderParams()}

      {/* İşlem butonu */}
      <button onClick={handleSubmit} className="action-button">Uygula</button>

      {/* Sonuç görüntüleme */}
      {resultUrl && (
        <div className="image-gallery">
          <div className="image-block">
            <h4>Sonuç</h4>
            <img src={resultUrl} alt="Sonuç" className="preview-image result" />
            <a href={resultUrl} download>
              <button className="download-button">İndir</button>
            </a>
          </div>
        </div>
      )}
    </div>
  );
}

export default App;
